(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x * 0.018 + t * 0.25) * 20 + Math.cos(y * 0.012 - t * 0.18) * 15;
  const warp1y = Math.cos(y * 0.02 - t * 0.22) * 18 + Math.sin(x * 0.015 + t * 0.3) * 12;
  const warp2x = Math.sin((x + y) * 0.01 + t * 0.15) * 10;
  const warp2y = Math.cos((x - y) * 0.01 - t * 0.2) * 10;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [120+Math.sin(t*0.4)*100, 60+Math.cos(t*0.3)*40, 0.09, 2.1, 0.0],
    [360+Math.cos(t*0.35)*90, 180+Math.sin(t*0.45)*50, 0.07, 1.8, 0.5],
    [240+Math.sin(t*0.25+2)*130, 120+Math.cos(t*0.4+1)*80, 0.055, 2.5, 1.0],
    [80+Math.cos(t*0.6+1)*70, 160+Math.sin(t*0.5+3)*60, 0.11, 1.6, 1.5],
    [400+Math.sin(t*0.3+4)*80, 50+Math.cos(t*0.7+2)*60, 0.065, 2.8, 2.0],
    [200+Math.cos(t*0.3+5)*110, 200+Math.sin(t*0.45)*70, 0.08, 2.0, 2.5],
    [300+Math.sin(t*0.5+3)*60, 100+Math.cos(t*0.35+4)*90, 0.1, 1.9, 3.0],
    [160+Math.cos(t*0.2+1.5)*90, 30+Math.sin(t*0.55+0.5)*40, 0.075, 2.3, 3.5]
  ];
  let aS = 0, iS = 0, diff = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp + ph);
    aS += wave;
    iS += Math.sin(d*f*0.65 + t*sp*0.5 + ph + 1.8);
    diff += Math.sin(d*f*1.3 - t*sp*0.8 + ph*2) * Math.cos(d*f*0.4 + t*sp*0.3);
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, dif = diff/n;
  const bg1 = Math.sin(sx*0.035 + sy*0.02 + t*0.7);
  const bg2 = Math.sin(sx*0.025 - sy*0.035 + t*0.9);
  const bg3 = Math.sin((sx+sy)*0.1 + t*2.2) * 0.3;
  const bg4 = Math.sin((sx-sy)*0.08 - t*1.8) * 0.25;
  const bg5 = Math.sin(sx*0.06 + t*1.5) * Math.sin(sy*0.06 - t*1.2) * 0.4;
  const bg = (bg1 + bg2 + bg3 + bg4 + bg5) / 2.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045 - ang*3.5 - t*1.3);
  const sp2 = Math.sin(dist*0.035 + ang*4.5 - t*1.0);
  const sp3 = Math.sin(dist*0.08 - ang*2 - t*2.0) * 0.3;
  const spiral = (sp1 + sp2 + sp3) * 0.35;
  const react = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + dif*0.4) * 2.5);
  const lap = Math.sin(sx*0.16)*Math.sin(sy*0.16) + Math.sin((sx+sy)*0.11+t)*0.4 + Math.sin((sx*0.7-sy*1.3)*0.08+t*0.6)*0.3;
  const cell = Math.tanh(lap * 1.6) * 0.25;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend = react*0.65 + cell*0.25 + micro;
  const v = blend*0.5+0.5;
  const breath = 0.85 + Math.sin(t*0.4)*0.1 + Math.sin(t*0.7+1)*0.05;
  const pal = [
    [5,12,52],[10,45,85],[12,80,105],[18,125,120],[45,160,110],
    [120,175,75],[195,185,50],[220,155,45],[215,105,55],[185,60,60],
    [140,35,55],[85,20,55],[40,15,50],[15,12,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const cr = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const cg = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const cb = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const glow = Math.max(0, Math.abs(react)-0.55)*3;
  const edge = Math.abs(react)>0.72 ? 1.2 : 1.0;
  const lum = breath * edge + glow * 0.15;
  return [
    Math.min(255, (cr*lum + glow*30)|0),
    Math.min(255, (cg*lum + glow*25)|0),
    Math.min(255, (cb*lum + glow*35)|0)
  ];
}
